import os
import shutil

def task_func(src_folder, backup_dir):
    if not os.path.isdir(src_folder):
        raise ValueError("The source folder does not exist.")

    src_abs = os.path.abspath(src_folder)
    backup_abs = os.path.abspath(backup_dir)
    src_name = os.path.basename(os.path.normpath(src_abs))
    target_abs = os.path.join(backup_abs, src_name)

    if os.path.commonpath([src_abs, backup_abs]) == src_abs:
        return False

    try:
        os.makedirs(backup_abs, exist_ok=True)

        if os.path.exists(target_abs) and not os.path.isdir(target_abs):
            return False

        shutil.copytree(src_abs, target_abs, dirs_exist_ok=True)
    except Exception:
        return False

    try:
        shutil.rmtree(src_abs)
    except Exception as exc:
        raise Exception(f"Error deleting source folder: {exc}") from exc

    return True
